const status=document.querySelector('#tool-status');
const track=(action)=>{if(typeof window.gtag==='function')window.gtag('event',action,{tool_name:location.pathname.split('/').filter(Boolean).pop()});};
function download(text,name){const blob=new Blob([text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const form=document.querySelector('#website-brief');
if(form){form.addEventListener('submit',event=>{event.preventDefault();const values=new FormData(form);const get=key=>String(values.get(key)||'').trim()||'To be confirmed';const result=`WEBSITE PROJECT BRIEF\n\nProject: ${get('business')}\nWebsite type: ${get('type')}\n\n1. Primary goal\n${get('goal')}\n\n2. Intended audience\n${get('audience')}\n\n3. Pages and content\n${get('pages')}\n\n4. Essential features\n${get('features')}\n\n5. Integrations\n${get('connections')}\n\n6. Content readiness and ongoing ownership\n${get('readiness')}\n\n7. Budget, timing and constraints\n${get('constraints')}\n\n8. Questions to resolve with the developer\n- Which features belong in the first release, and which can wait?\n- What content, access and provider accounts are needed?\n- What are the acceptance criteria for each key user journey?\n- Who handles hosting, maintenance, backups and support?\n- How will enquiries and successful user actions be measured?\n\n9. Suggested acceptance checks\n- Complete the primary visitor journey on a phone and desktop.\n- Test forms, confirmations and error handling.\n- Review titles, links, redirects and indexing settings.\n- Confirm ownership and the process for ongoing updates.\n\nPrepared with DevMania's free website brief builder.\nhttps://www.dev-mania.com/tools/website-brief-builder/\nPlanning template only; scope and pricing require review.`;document.querySelector('#brief-output').value=result;document.querySelectorAll('[data-copy],[data-download]').forEach(b=>b.disabled=false);status.textContent='Your brief is ready. Edit it, copy it or download it before leaving.';track('brief_created');});}
document.querySelector('[data-copy]')?.addEventListener('click',async event=>{const output=document.getElementById(event.currentTarget.dataset.copy);try{await navigator.clipboard.writeText(output.value);status.textContent='Brief copied.';track('brief_copied');}catch{output.focus();output.select();status.textContent='Select and copy the brief using your browser’s copy command.';}});
document.querySelector('[data-download]')?.addEventListener('click',()=>{download(document.querySelector('#brief-output').value,'website-project-brief.txt');status.textContent='Brief downloaded.';track('brief_downloaded');});
const checks=[...document.querySelectorAll('[data-launch-check]')];
checks.forEach(input=>input.addEventListener('change',()=>{const completed=checks.filter(c=>c.checked).length;document.querySelector('#check-progress').textContent=`${completed} of ${checks.length} checks completed`;document.querySelector('#launch-progress').value=completed;}));
document.querySelector('#download-checklist')?.addEventListener('click',()=>{const remaining=checks.filter(c=>!c.checked).map(c=>'- '+c.value);download('WEBSITE LAUNCH — REMAINING CHECKS\n\n'+(remaining.join('\n')||'All checks marked complete. Review any project-specific requirements before launch.')+'\n\nManual checklist, not an automated audit.\nhttps://www.dev-mania.com/tools/website-launch-checklist/','website-launch-checklist.txt');status.textContent='Remaining tasks downloaded.';track('checklist_downloaded');});
